'use client';
import {useEffect,useState} from 'react';
import {enqueueOperation,flushOperations,pendingOperations} from '../lib/offline';


const API=(process.env.NEXT_PUBLIC_API_URL||'https://clinai-api.onrender.com').replace(/\/$/,'');
type Row=Record<string,any>;
type Field={key:string;label:string;type?:string;placeholder?:string;options?:string[];required?:boolean};

const groups:any[]=[
 ['CARE',['patients','appointments','registration','queue','triage','encounters','clinical-notes','diagnoses','orders','care-plans','referrals','referral-transfers','follow-up','care-tasks']],
 ['CLINICAL',['laboratory','imaging','pharmacy','nursing','emergency','inpatient','beds','surgery','maternity','pediatrics','child-health','immunization','chronic-care','medication-reconciliation','consents']],
 ['FINANCE',['billing','payments','insurance','claims','accounting']],
 ['SUPPLY',['inventory','procurement','suppliers']],
 ['PATIENT',['patient-portal','portal-messages','telemedicine','remote-monitoring','notifications','documents']],
 ['PUBLIC HEALTH',['surveillance','investigations','response','mortality','population-health','district-intelligence']],
 ['OPERATIONS',['staff','facilities','facility-capacity','facility-resources','facility-incidents','facility-performance','referral-network']],
 ['INTELLIGENCE',['ai','ai-evaluations','analytics','care-gaps','care-graph']],
 ['TRUST & CONNECTIONS',['tasks','workflows','interoperability','health-connections','audit','security','settings','terminology','guidelines','care-pathways','reporting','offline-sync']]
];
const journey:any[]=[['Registration','registration'],['Check-in','queue'],['Triage','triage'],['Care visit','encounters'],['Diagnosis','diagnoses'],['Orders','orders'],['Laboratory','laboratory'],['Imaging','imaging'],['Medication','pharmacy'],['Nursing','nursing'],['Emergency','emergency'],['Admission','inpatient'],['Bed','beds'],['Surgery','surgery'],['Maternity','maternity'],['Child health','pediatrics'],['Immunization','immunization'],['Chronic care','chronic-care'],['Referral','referrals'],['Transfer','referral-transfers'],['Billing','billing'],['Payment','payments'],['Discharge','inpatient'],['Follow-up','follow-up'],['Telemedicine','telemedicine'],['Monitoring','remote-monitoring'],['Patient access','patient-portal'],['Care tasks','care-tasks'],['Population health','population-health'],['District view','district-intelligence']];
const navShort:any={patients:'PT',appointments:'AP',queue:'Q',triage:'TR',encounters:'EN',laboratory:'LAB',pharmacy:'RX',maternity:'MAT',pediatrics:'PED',immunization:'IMM',billing:'₤',inventory:'INV',telemedicine:'TEL',analytics:'AN',facilities:'FAC',tasks:'TS',settings:'⚙'};
const navIcon=(x:string)=>navShort[x]||pretty(x).slice(0,2).toUpperCase();
const pretty=(x:string)=>x.replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase());
const primaryMobile=[['Home','command-center'],['Patients','patients'],['Queue','queue'],['Tasks','tasks']];
const fields:Record<string,Field[]>={
 patients:[{key:'firstName',label:'First name',required:true},{key:'lastName',label:'Last name',required:true},{key:'phone',label:'Phone'}],
 appointments:[{key:'patientId',label:'Patient ID'},{key:'startAt',label:'Start date/time',type:'datetime-local'},{key:'reason',label:'Reason'}],
 registration:[{key:'patientId',label:'Patient ID'},{key:'status',label:'Status',options:['registered','checked-in','completed']}],
 queue:[{key:'patientId',label:'Patient ID'},{key:'priority',label:'Priority',options:['normal','routine','urgent','emergency','stat']}],
 triage:[{key:'patientId',label:'Patient ID'},{key:'encounterId',label:'Encounter ID'},{key:'chiefComplaint',label:'Chief complaint'},{key:'temperature',label:'Temperature'},{key:'heartRate',label:'Heart rate'},{key:'respiratoryRate',label:'Respiratory rate'},{key:'systolic',label:'Systolic BP'},{key:'diastolic',label:'Diastolic BP'},{key:'spo2',label:'SpO₂'},{key:'pain',label:'Pain 0 to 10'},{key:'acuity',label:'Acuity',options:['routine','urgent','emergency']}],
 encounters:[{key:'patientId',label:'Patient ID'},{key:'appointmentId',label:'Appointment ID'},{key:'reason',label:'Reason'}],
 'clinical-notes':[{key:'encounterId',label:'Encounter ID'},{key:'noteType',label:'Note type',options:['SOAP','progress','discharge','nursing']},{key:'subjective',label:'Subjective'},{key:'objective',label:'Objective'},{key:'assessment',label:'Assessment'},{key:'plan',label:'Plan'}],
 diagnoses:[{key:'patientId',label:'Patient ID'},{key:'encounterId',label:'Encounter ID'},{key:'code',label:'Diagnosis code'},{key:'description',label:'Diagnosis description'}],
 orders:[{key:'patientId',label:'Patient ID'},{key:'encounterId',label:'Encounter ID'},{key:'code',label:'Order code'},{key:'description',label:'Description'},{key:'category',label:'Category',options:['laboratory','imaging','medication','procedure']},{key:'priority',label:'Priority',options:['routine','urgent','stat']}],
 laboratory:[{key:'patientId',label:'Patient ID'},{key:'code',label:'Test code'},{key:'description',label:'Test name'},{key:'priority',label:'Priority',options:['routine','urgent','stat']}],
 imaging:[{key:'patientId',label:'Patient ID'},{key:'code',label:'Study code'},{key:'description',label:'Study'},{key:'priority',label:'Priority',options:['routine','urgent','stat']}],
 pharmacy:[{key:'patientId',label:'Patient ID'},{key:'medicationCode',label:'Medication code'},{key:'medicationName',label:'Medication name'},{key:'dose',label:'Dose'},{key:'frequency',label:'Frequency'},{key:'route',label:'Route'},{key:'duration',label:'Duration'},{key:'quantity',label:'Quantity'}],
 nursing:[{key:'patientId',label:'Patient ID'},{key:'assessmentType',label:'Assessment type'},{key:'painScore',label:'Pain score'},{key:'riskFlags',label:'Risk flags'}],
 emergency:[{key:'patientId',label:'Patient ID'},{key:'chiefComplaint',label:'Chief complaint'},{key:'acuity',label:'Acuity',options:['urgent','emergency']},{key:'triageLevel',label:'Triage level'}],
 inpatient:[{key:'patientId',label:'Patient ID'},{key:'ward',label:'Ward'},{key:'bed',label:'Bed'}],
 beds:[{key:'ward',label:'Ward'},{key:'bedNumber',label:'Bed number'},{key:'status',label:'Status',options:['available','occupied','cleaning','blocked']}],
 surgery:[{key:'patientId',label:'Patient ID'},{key:'procedureName',label:'Procedure'},{key:'scheduledAt',label:'Scheduled date/time',type:'datetime-local'},{key:'consentConfirmed',label:'Consent confirmed',options:['true','false']}],
 maternity:[{key:'patientId',label:'Patient ID'},{key:'contactNumber',label:'ANC contact number'},{key:'contactDate',label:'Contact date/time',type:'datetime-local'},{key:'gestationalAgeWeeks',label:'Gestational age weeks'},{key:'gravida',label:'Gravida'},{key:'para',label:'Para'},{key:'symphysioFundalHeight',label:'Symphysio-fundal height'},{key:'assessment',label:'Assessment'},{key:'plan',label:'Plan'}],
 pediatrics:[{key:'patientId',label:'Patient ID'},{key:'ageMonths',label:'Age months'},{key:'weightKg',label:'Weight kg'},{key:'heightCm',label:'Height cm'},{key:'muacMm',label:'MUAC mm'},{key:'temperature',label:'Temperature'},{key:'respiratoryRate',label:'Respiratory rate'},{key:'spo2',label:'SpO₂'}],
 immunization:[{key:'patientId',label:'Patient ID'},{key:'vaccineCode',label:'Vaccine code'},{key:'vaccineName',label:'Vaccine name'},{key:'doseNumber',label:'Dose number'},{key:'lotNumber',label:'Lot number'},{key:'expiryDate',label:'Expiry date',type:'date'},{key:'route',label:'Route'},{key:'site',label:'Site'},{key:'nextDueAt',label:'Next due',type:'datetime-local'}],
 'chronic-care':[{key:'patientId',label:'Patient ID'},{key:'conditionCode',label:'Condition code'},{key:'conditionName',label:'Condition name'},{key:'status',label:'Status',options:['active','stable','uncontrolled','resolved']},{key:'riskLevel',label:'Risk level',options:['low','moderate','high','critical']},{key:'nextReviewAt',label:'Next review',type:'datetime-local'}],
 'care-plans':[{key:'patientId',label:'Patient ID'},{key:'encounterId',label:'Encounter ID'},{key:'problem',label:'Care problem'},{key:'goal',label:'Goal'},{key:'status',label:'Status'}],
 referrals:[{key:'patientId',label:'Patient ID'},{key:'encounterId',label:'Encounter ID'},{key:'reason',label:'Referral reason'},{key:'destination',label:'Destination'}],
 'follow-up':[{key:'patientId',label:'Patient ID'},{key:'reason',label:'Follow-up reason'},{key:'dueAt',label:'Due date/time',type:'datetime-local'}],
 billing:[{key:'patientId',label:'Patient ID'},{key:'encounterId',label:'Encounter ID'},{key:'description',label:'Charge description'},{key:'total',label:'Total'},{key:'currency',label:'Currency',options:['UGX','USD','EUR','KES','TZS']}],
 payments:[{key:'invoiceId',label:'Invoice ID'},{key:'amount',label:'Amount'},{key:'method',label:'Method',options:['cash','mobile-money','card','bank']}],
 insurance:[{key:'patientId',label:'Patient ID'},{key:'provider',label:'Provider'},{key:'policyNumber',label:'Policy number'}],
 claims:[{key:'patientId',label:'Patient ID'},{key:'claimNumber',label:'Claim number'},{key:'status',label:'Status',options:['draft','submitted','approved','rejected']}],
 accounting:[{key:'description',label:'Entry description'},{key:'amount',label:'Amount'},{key:'type',label:'Type',options:['income','expense','adjustment']}],
 inventory:[{key:'name',label:'Item name'},{key:'sku',label:'SKU'},{key:'quantity',label:'Quantity'},{key:'unit',label:'Unit'}],
 procurement:[{key:'supplier',label:'Supplier'},{key:'description',label:'Order description'},{key:'quantity',label:'Quantity'}],
 suppliers:[{key:'name',label:'Supplier name'},{key:'phone',label:'Phone'},{key:'email',label:'Email'}],
 'patient-portal':[{key:'patientId',label:'Patient ID'},{key:'feature',label:'Portal feature'},{key:'status',label:'Status'}],
 telemedicine:[{key:'patientId',label:'Patient ID'},{key:'scheduledAt',label:'Scheduled date/time',type:'datetime-local'},{key:'meetingUrl',label:'Meeting URL'},{key:'consentConfirmed',label:'Consent confirmed',options:['true','false']}],
 'remote-monitoring':[{key:'patientId',label:'Patient ID'},{key:'deviceId',label:'Device ID'},{key:'metric',label:'Metric'},{key:'valueNumeric',label:'Value'},{key:'unit',label:'Unit'},{key:'measuredAt',label:'Measured at',type:'datetime-local'}],
 notifications:[{key:'patientId',label:'Patient ID'},{key:'channel',label:'Channel',options:['in-app','sms','email','whatsapp']},{key:'message',label:'Message'}],
 documents:[{key:'patientId',label:'Patient ID'},{key:'name',label:'Document name'},{key:'type',label:'Document type'}],
 ai:[{key:'patientId',label:'Patient ID'},{key:'purpose',label:'AI purpose',required:true},{key:'question',label:'Clinical question',required:true},{key:'clinicalContext',label:'Clinical context JSON'}],
 analytics:[{key:'name',label:'Metric name'},{key:'value',label:'Value'},{key:'period',label:'Period'}],
 'population-health':[{key:'name',label:'Population metric'},{key:'value',label:'Value'},{key:'period',label:'Period'}],
 staff:[{key:'name',label:'Staff name'},{key:'role',label:'Role'},{key:'phone',label:'Phone'}],
 facilities:[{key:'name',label:'Facility name'},{key:'type',label:'Facility type'},{key:'status',label:'Status'}],
 tasks:[{key:'title',label:'Task title'},{key:'patientId',label:'Patient ID'},{key:'priority',label:'Priority',options:['normal','urgent','critical']}],
 workflows:[{key:'name',label:'Workflow name'},{key:'trigger',label:'Trigger'},{key:'status',label:'Status'}],
 interoperability:[{key:'system',label:'Connected system'},{key:'standard',label:'Standard',options:['FHIR','HL7v2','DICOM','DHIS2']},{key:'status',label:'Status'}],
 terminology:[{key:'system',label:'Terminology system'},{key:'code',label:'Code'},{key:'display',label:'Display'},{key:'version',label:'Version'}],
 guidelines:[{key:'title',label:'Guideline title'},{key:'domain',label:'Domain'},{key:'jurisdiction',label:'Jurisdiction',options:['UG','INTL']},{key:'version',label:'Version'},{key:'sourceUrl',label:'Source URL'}],
 'care-pathways':[{key:'code',label:'Pathway code'},{key:'name',label:'Pathway name'},{key:'domain',label:'Domain'},{key:'jurisdiction',label:'Jurisdiction',options:['UG','INTL']},{key:'version',label:'Version'}],
 hie:[{key:'name',label:'Connection name'},{key:'protocol',label:'Protocol',options:['FHIR','HL7v2','DICOM','DHIS2']},{key:'baseUrl',label:'Base URL'},{key:'status',label:'Status',options:['disabled','testing','active']}],
 reporting:[{key:'reportingSystem',label:'Reporting system'},{key:'indicatorCode',label:'Indicator code'},{key:'indicatorName',label:'Indicator name'},{key:'periodGranularity',label:'Period',options:['daily','weekly','monthly','quarterly','annual']}],
 'offline-sync':[{key:'deviceId',label:'Device ID'},{key:'resourceType',label:'Resource type'},{key:'operation',label:'Operation',options:['create','update','delete']},{key:'operationId',label:'Operation ID'}],
 trust:[{key:'control',label:'Control'},{key:'status',label:'Status'}],
 audit:[{key:'action',label:'Action'},{key:'entityType',label:'Entity type'},{key:'entityId',label:'Entity ID'}],
 settings:[{key:'name',label:'Setting name'},{key:'value',label:'Value'}]
};

function Logo({compact=false}:{compact?:boolean}){return <div className={`brandlockup ${compact?'compact':''}`}><img src={compact?'/clinai-icon.png':'/clinai-logo.png'} alt="ClinAI"/><span>Better care, connected</span></div>}

function NavContent({module,setModule,close}:{module:string;setModule:(m:string)=>void;close?:()=>void}){return <>
 <button className={`nav-home ${module==='command-center'?'active':''}`} onClick={()=>{setModule('command-center');close?.()}}><span className="navglyph">⌂</span><span>Home</span></button>
 {groups.map(([g,items]:any)=><section key={g}><small>{g}</small>{items.map((x:string)=><button key={x} className={module===x?'active':''} onClick={()=>{setModule(x);close?.()}}><span className="navglyph">{navIcon(x)}</span><span>{pretty(x)}</span></button>)}</section>)}
 </>}

export default function Home(){
 const [token,setToken]=useState(''),[online,setOnline]=useState(true),[pending,setPending]=useState(0),[module,setModule]=useState('command-center'),[rows,setRows]=useState<Row[]>([]),[dash,setDash]=useState<Row>({}),[status,setStatus]=useState('Connecting'),[error,setError]=useState(''),[search,setSearch]=useState(''),[patient360,setPatient360]=useState<Row|null>(null),[encounter,setEncounter]=useState<Row|null>(null),[searchResults,setSearchResults]=useState<Row>({}),[navOpen,setNavOpen]=useState(false);
 async function login(){try{const r=await fetch(`${API}/api/auth/demo`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Login failed');setToken(d.token)}catch(e:any){setError(e.message);setStatus('Offline')}}
 async function load(){if(!token||module==='command-center'){setRows([]);return}setStatus('Loading');setError('');try{const endpoint=module==='laboratory'?'/api/laboratory/results':`/api/${module}`;const r=await fetch(`${API}${endpoint}`,{headers:{Authorization:`Bearer ${token}`}});const d=await r.json();if(!r.ok)throw new Error(d.error||`Unable to load ${pretty(module)}`);setRows(d.data||[]);setStatus('Ready')}catch(e:any){setRows([]);setError(e.message);setStatus('Error')}}
 async function refreshDash(){if(!token)return;try{const r=await fetch(`${API}/api/dashboard`,{headers:{Authorization:`Bearer ${token}`}});if(r.ok)setDash(await r.json())}catch{}}
 async function runSearch(){if(!token||search.trim().length<2){setSearchResults({});return}try{const r=await fetch(`${API}/api/search?q=${encodeURIComponent(search.trim())}`,{headers:{Authorization:`Bearer ${token}`}});const d=await r.json();setSearchResults(d)}catch{setSearchResults({})}}
 async function openPatient(id:string){try{const r=await fetch(`${API}/api/patients/${id}/360`,{headers:{Authorization:`Bearer ${token}`}});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to open patient');setPatient360(d)}catch(e:any){setError(e.message)}}
 useEffect(()=>{login();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const sync=async()=>{setOnline(navigator.onLine);if(navigator.onLine&&token)await flushOperations(token).catch(()=>{});setPending((await pendingOperations().catch(()=>[])).length)};window.addEventListener('online',sync);window.addEventListener('offline',sync);sync();return()=>{window.removeEventListener('online',sync);window.removeEventListener('offline',sync)}},[token]);
 useEffect(()=>{if(token){load();refreshDash()}},[token,module]);
 const title=module==='command-center'?'Home':pretty(module);
 const selectModule=(m:string)=>{setModule(m);setError('');setSearchResults({});setNavOpen(false)};
 const metrics=[['Patients',dash.patients],['Appointments',dash.appointments],['Waiting',dash.waiting],['Critical labs',dash.criticalLabs],['Open tasks',dash.openTasks],['Unpaid',dash.unpaid]];
 return <main className="app-shell">
  <aside className="desktop-sidebar"><Logo/><NavContent module={module} setModule={selectModule}/><div className="sidebar-footer"><span className="secure-dot"/> Care that stays connected</div></aside>
  <aside className="tablet-rail"><Logo compact/><button className="rail-menu" onClick={()=>setNavOpen(true)} aria-label="Open navigation">☰</button>{[['command-center','⌂'],...primaryMobile.slice(1).map(([_,m])=>[m,navIcon(m)])].map(([m,i]:any)=><button key={m} className={module===m?'active':''} onClick={()=>selectModule(m)}><b>{i}</b><span>{pretty(m)}</span></button>)}</aside>
  <div className="app-main">
   <header className="topbar">
    <div className="mobile-brand"><button className="icon-button menu-button" onClick={()=>setNavOpen(true)} aria-label="Open menu">☰</button><Logo compact/></div>
    <div className="topbar-search"><span>⌕</span><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==='Enter'&&runSearch()} placeholder="Search patients, encounters, appointments..."/><button onClick={runSearch}>Search</button></div>
    <div className="topbar-actions">{!online&&<span className="connection offline">Offline mode{pending?` · ${pending} queued`:''}</span>}<span className={`connection ${status.toLowerCase()}`}><i aria-hidden="true"/> {status}</span><button className="icon-button" title="Notifications">♢</button><div className="user-chip"><span>CL</span><b>Clinician</b></div></div>
   </header>
   <div className="content">
    <header className="page-header"><div><div className="eyebrow">CLINAI <span>•</span> UGANDA</div><h1>{title}</h1><p>Everything your care team needs, together.</p></div><div className="page-status"><span className="secure-dot"/> {status}</div></header>
    <div className="mobile-search"><div className="searchbox"><span>⌕</span><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==='Enter'&&runSearch()} placeholder="Search a patient or record"/><button onClick={runSearch}>Go</button></div></div>
    {Object.keys(searchResults).length>0&&<section className="search-results panel"><div className="panel-title"><div><span className="section-kicker">FIND</span><h2>Results</h2></div><button className="ghost" onClick={()=>setSearchResults({})}>Clear</button></div><div className="search-grid">{Object.entries(searchResults).map(([k,v]:any)=><div key={k}><small>{pretty(k)}</small>{(v||[]).map((r:Row)=><button key={r.id} onClick={()=>r.firstName&&openPatient(r.id)}>{r.firstName?`${r.firstName} ${r.lastName}`:r.display||r.reason||r.status||r.id}</button>)}</div>)}</div></section>}
    {module==='command-center'?<CommandCenter dash={dash} metrics={metrics} setModule={selectModule} journey={journey} token={token}/>:module==='ai'?<AIWorkspace token={token}/>:<ModuleWorkspace module={module} title={title} rows={rows} token={token} error={error} load={load} refreshDash={refreshDash} openPatient={openPatient} setEncounter={setEncounter} />}
   </div>
  </div>
  <nav className="mobile-bottom-nav">{primaryMobile.map(([label,m])=><button key={m} className={module===m?'active':''} onClick={()=>selectModule(m)}><span>{m==='command-center'?'⌂':m==='patients'?'PT':m==='queue'?'Q':'TS'}</span><small>{label}</small></button>)}<button onClick={()=>setNavOpen(true)}><span>•••</span><small>More</small></button></nav>
  {navOpen&&<div className="nav-overlay" onClick={()=>setNavOpen(false)}><aside className="nav-drawer" onClick={e=>e.stopPropagation()}><div className="drawer-head"><Logo/><button className="icon-button" onClick={()=>setNavOpen(false)}>×</button></div><NavContent module={module} setModule={selectModule} close={()=>setNavOpen(false)}/></aside></div>}
  {patient360&&<Patient360 data={patient360} token={token} close={()=>setPatient360(null)} setModule={selectModule}/>} {encounter&&<EncounterWorkspace data={encounter} token={token} close={()=>setEncounter(null)} done={()=>{load();refreshDash()}}/>}
 </main>
}

function CommandCenter({dash,metrics,setModule,journey,token}:{dash:Row;metrics:any[];setModule:(m:string)=>void;journey:any[];token:string}){
 const [intel,setIntel]=useState<Row>({}); const [role,setRole]=useState('Leadership');
 useEffect(()=>{if(!token)return;fetch(`${API}/api/analytics/command-center`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>setIntel(d.data||{})).catch(()=>{})},[token]);
 const o=intel.overview||{}; const trend=intel.trend||[]; const maxTrend=Math.max(1,...trend.map((x:Row)=>Number(x.appointments||0)));
 const roleCards:Record<string,Array<[string,string,string]>>={Leadership:[['Today','patients and service pressure','analytics'],['Financial health','billing and collection','billing'],['Facility readiness','capacity and incidents','facilities']],Doctor:[['My care','active encounters and follow-up','encounters'],['Results','laboratory and imaging review','laboratory'],['Tasks','clinical work needing attention','care-tasks']],Nurse:[['Patient flow','triage and waiting','queue'],['Care tasks','observations and bedside work','nursing'],['Escalations','urgent patients and alerts','emergency']],Pharmacist:[['Dispensing','prescriptions waiting','pharmacy'],['Stock','items needing attention','inventory'],['Reviews','medication reconciliation','medication-reconciliation']]};
 const cards=roleCards[role]||roleCards.Leadership;
 return <div className="command-center">
  <section className="welcome-panel"><div><span className="section-kicker">COMMAND CENTER</span><h2>Care, clearly in view.</h2><p>See patient flow, clinical attention, financial pressure and facility readiness without opening separate screens.</p></div><div className="welcome-mark"><img src="/clinai-icon.png" alt="ClinAI"/></div></section>
  <section className="panel ai-command-card"><div><span className="section-kicker">CLINAI INTELLIGENCE</span><h2>What needs attention today?</h2><p>Ask ClinAI to interpret the current operational and clinical picture.</p></div><button className="primary" onClick={()=>setModule('ai')}>Ask ClinAI →</button></section>
  <section className="metric-grid command-kpis">{[['Patients',o.patients??dash.patients,'registered'],['Appointments',o.appointments_today??dash.appointments,'today'],['Waiting',o.waiting??dash.waiting,'in care flow'],['Active care',o.active_encounters??0,'consultations'],['Beds occupied',o.occupied_beds??0,'inpatient'],['Open tasks',o.open_tasks??dash.openTasks,'need attention']].map(([n,v,s],i)=><div className={`metric-card metric-${i}`} key={String(n)}><span>{n}</span><strong>{v}</strong><small>{s}</small></div>)}</section>
  <section className="dashboard-toolbar panel"><div><span className="section-kicker">WORKSPACE VIEW</span><h2>Focus for your role</h2></div><div className="role-switch">{['Leadership','Doctor','Nurse','Pharmacist'].map(x=><button key={x} className={role===x?'active':''} onClick={()=>setRole(x)}>{x}</button>)}</div></section>
  <section className="dashboard-focus-grid">{cards.map(([label,desc,target])=><button className="focus-card panel" key={label} onClick={()=>setModule(target)}><span className="section-kicker">{label.toUpperCase()}</span><strong>{desc}</strong><span>Open workspace →</span></button>)}</section>
  <section className="dashboard-grid">
   <div className="panel"><div className="panel-title"><div><span className="section-kicker">PATIENT FLOW</span><h2>Where people are now</h2></div><button className="ghost" onClick={()=>setModule('queue')}>Open queue</button></div><div className="flow-pipeline">{(intel.queue||[]).slice(0,6).map((x:Row)=><button key={`${x.status}-${x.priority}`} onClick={()=>setModule('queue')}><b>{x.count}</b><span>{pretty(x.status)}</span><small>{x.priority}</small></button>)}{!(intel.queue||[]).length&&<div className="dashboard-empty">No active queue entries yet.</div>}</div></div>
   <div className="panel"><div className="panel-title"><div><span className="section-kicker">CLINICAL ATTENTION</span><h2>Needs review</h2></div></div><div className="attention-list">{(intel.clinical||[]).map((x:Row)=><button key={x.label} onClick={()=>setModule(x.label.includes('laboratory')?'laboratory':x.label.includes('Medication')?'medication-reconciliation':'care-tasks')}><span>{x.label}</span><strong>{x.count}</strong></button>)}</div></div>
  </section>
  <section className="dashboard-grid">
   <div className="panel trend-panel"><div className="panel-title"><div><span className="section-kicker">LAST 7 DAYS</span><h2>Appointments and care activity</h2></div><button className="ghost" onClick={()=>setModule('analytics')}>Full analytics</button></div><div className="trend-chart">{trend.map((x:Row)=><div className="trend-day" key={x.d}><div className="trend-bars"><i style={{height:`${Math.max(8,(Number(x.appointments||0)/maxTrend)*100)}%`}}/><em style={{height:`${Math.max(8,(Number(x.encounters||0)/Math.max(1,maxTrend))*100)}%`}}/></div><small>{String(x.d).slice(5)}</small></div>)}</div><div className="chart-legend"><span><i/>Appointments</span><span><em/>Care visits</span></div></div>
   <div className="panel"><div className="panel-title"><div><span className="section-kicker">FINANCE</span><h2>Revenue at a glance</h2></div><button className="ghost" onClick={()=>setModule('billing')}>Billing</button></div><div className="finance-summary"><div><span>Billed</span><strong>{Number(intel.finance?.billed||0).toLocaleString()} UGX</strong></div><div><span>Paid invoices</span><strong>{intel.finance?.paid||0}</strong></div><div><span>Open invoices</span><strong>{intel.finance?.open||0}</strong></div><div><span>Outstanding</span><strong>{Number(o.outstanding_balance||0).toLocaleString()} UGX</strong></div></div></div>
  </section>
  <section className="panel"><div className="panel-title"><div><span className="section-kicker">FACILITY READINESS</span><h2>Service pressure across facilities</h2></div><button className="ghost" onClick={()=>setModule('district-intelligence')}>District intelligence</button></div><div className="facility-dashboard">{(intel.facilities||[]).map((f:Row)=><button key={f.id} onClick={()=>setModule('facilities')}><div><strong>{f.name}</strong><small>{f.type||'Facility'}</small></div><span><b>{f.occupied_beds}</b> occupied</span><span><b>{f.available_beds}</b> available</span><span className={Number(f.open_incidents)>0?'facility-alert':''}><b>{f.open_incidents}</b> incidents</span></button>)}{!(intel.facilities||[]).length&&<div className="dashboard-empty">Facility readiness will appear here as facilities are configured.</div>}</div></section>
  <section className="command-grid"><div className="panel focus-panel"><div className="panel-title"><div><span className="section-kicker">QUICK ACTIONS</span><h2>Start with what matters</h2></div></div><div className="quick-actions"><button onClick={()=>setModule('patients')}><b>+</b><span><strong>Register patient</strong><small>Start a new patient record</small></span></button><button onClick={()=>setModule('triage')}><b>TR</b><span><strong>Open triage</strong><small>Record vitals and urgency</small></span></button><button onClick={()=>setModule('queue')}><b>Q</b><span><strong>View queue</strong><small>Manage patient flow</small></span></button><button onClick={()=>setModule('appointments')}><b>AP</b><span><strong>Appointments</strong><small>See today's schedule</small></span></button></div></div><div className="panel journey-panel"><div className="panel-title"><div><span className="section-kicker">CARE JOURNEY</span><h2>Patient journey</h2></div><span className="journey-note-inline">{journey.length} steps</span></div><div className="journey-steps">{journey.map(([label,m]:any,i:number)=><button key={label} onClick={()=>setModule(m)}><i>{String(i+1).padStart(2,'0')}</i><span>{label}</span><em>Open</em></button>)}</div><button className="view-all" onClick={()=>setModule('patients')}>Open patient care <span>→</span></button></div></section>
 </div>
}
function ModuleWorkspace({module,title,rows,token,error,load,refreshDash,openPatient,setEncounter}:{module:string;title:string;rows:Row[];token:string;error:string;load:()=>void;refreshDash:()=>void;openPatient:(id:string)=>void;setEncounter:(row:Row)=>void}){return <>
 <section className="workspace-panel panel"><div className="panel-title"><div><span className="section-kicker">{module==='patients'?'PATIENTS':'CARE'}</span><h2>{title}</h2><p>{moduleDescription(module)}</p></div><button className="ghost refresh" onClick={()=>{load();refreshDash()}}>↻ Refresh</button></div>{error&&<div className="error">{error}</div>}<Action module={module} token={token} done={()=>{load();refreshDash()}}/><div className="record-list">{rows.length?rows.map(r=><RecordRow key={r.id} module={module} row={r} token={token} done={()=>{load();refreshDash()}} openPatient={openPatient} openEncounter={setEncounter}/>):<div className="empty-state"><div className="empty-icon">{module==='patients'?'PT':'+'}</div><strong>No {pretty(module).toLowerCase()} records yet</strong><span>Add the first record above, or refresh to see new activity.</span></div>}</div></section>
 </>}

function moduleDescription(module:string){const d:Record<string,string>={patients:'Register people and keep their care record together.',registration:'Start a new patient journey with identity and contact details.',queue:'See who is waiting and what should happen next.',triage:'Record the first assessment, vital signs and urgency.',encounters:'Bring the patient story, assessment and care plan together.',diagnoses:'Record the conditions being assessed or treated.',orders:'Request tests, medicines and procedures from one place.',laboratory:'Collect samples, review results and release verified findings.',imaging:'Schedule studies, record findings and share verified reports.',pharmacy:'Review prescriptions, stock and dispensing.',nursing:'Support bedside assessment, care tasks and medicine administration.',emergency:'Coordinate urgent assessment, treatment and disposition.',inpatient:'Manage admissions, ward care, transfers and discharge.',beds:'See available beds and assign them safely.',surgery:'Coordinate preparation, procedure, recovery and follow-up.',maternity:'Follow pregnancy, birth, newborn and postnatal care.',pediatrics:'Follow child health, growth, illness and development.',immunization:'Keep vaccination history and next visits clear.','chronic-care':'Follow long-term conditions, goals, medicines and reviews.',referrals:'Send care to the right service and track what happens next.','referral-transfers':'Coordinate acceptance, transport, arrival and handover.','care-tasks':'Keep important care work assigned and visible.','medication-reconciliation':'Compare medicines and resolve differences safely.',billing:'Prepare charges and track what is still due.',payments:'Record completed payments and receipts.',insurance:'Keep cover information available for care and billing.',claims:'Track requests sent to insurers.',accounting:'Follow income, expenses and financial entries.',inventory:'Know what supplies and medicines are available.',procurement:'Move requests from need to delivery.',suppliers:'Keep supplier details and purchasing relationships.','patient-portal':'Give patients a clear place to see and manage their care.','portal-messages':'Keep patient conversations together.',telemedicine:'Arrange and conduct remote care visits.','remote-monitoring':'Review readings and follow up when attention is needed.',notifications:'Keep patients and teams informed.',documents:'Keep important patient documents easy to find.',surveillance:'Track health events and cases for public health.',investigations:'Coordinate public health investigations and findings.',response:'Coordinate response work and follow-up.',mortality:'Review deaths and contributing information.','population-health':'Understand health patterns across groups.','district-intelligence':'See service capacity, pressure and performance across facilities.',facilities:'Manage facility identity and operational readiness.','facility-capacity':'See which services are available and how much can be handled.','facility-resources':'Follow equipment, supplies and service readiness.','facility-incidents':'Track operational problems and response.','facility-performance':'Review service quality and activity.','referral-network':'Understand how facilities connect for care.','care-gaps':'Find important follow-up that may have been missed.','care-graph':'See how events in a patient journey connect.',ai:'Get help organizing patient information while keeping clinical decisions with the care team.','ai-evaluations':'Review the quality and safety of assisted suggestions.',analytics:'Understand activity, trends and service performance.',tasks:'Work that needs an owner and a next step.',workflows:'Keep important work moving from one step to the next.',interoperability:'Connect approved health information services.','health-connections':'Manage approved connections with other health services.',audit:'See important activity and changes.',security:'Review access and important security events.',settings:'Manage how ClinAI works for your organization.',terminology:'Keep names and codes consistent.',guidelines:'Keep approved care guidance organized.','care-pathways':'Guide teams through approved care journeys.',reporting:'Prepare trusted health information for reporting.','offline-sync':'Keep field work ready for later synchronization.'};return d[module]||`Manage ${pretty(module).toLowerCase()} here.`}

function Action({module,token,done}:{module:string;token:string;done:()=>void}){const [d,setD]=useState<Row>({}),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');const fs=fields[module]||[{key:'name',label:'Name'},{key:'description',label:'Description'},{key:'status',label:'Status'}];
 async function submit(){setBusy(true);setMsg('');let body:any={...d};let url=`${API}/api/${module}`;try{if(['appointments','follow-up','surgery','telemedicine'].includes(module)){const key=module==='appointments'?'startAt':module==='follow-up'?'dueAt':'scheduledAt';if(body[key])body[key]=new Date(body[key]).toISOString()}if(module==='triage'){for(const k of ['temperature','heartRate','respiratoryRate','systolic','diastolic','spo2','pain'])if(body[k]!==undefined&&body[k]!=='')body[k]=Number(body[k])}if(module==='orders'){body.category=body.category||'laboratory';body.priority=body.priority||'routine'} 
 if(module==='nursing'&&body.medicationOrderId)url=`${API}/api/medication-administrations`;if(module==='laboratory'||module==='imaging')body={patientId:body.patientId,encounterId:body.encounterId,category:module==='laboratory'?'laboratory':'imaging',code:body.code||'GENERAL',description:body.description,priority:body.priority||'routine'};if(module==='laboratory'||module==='imaging')url=`${API}/api/orders`;if(module==='emergency')url=`${API}/api/emergency/cases`;if(module==='inpatient')url=`${API}/api/inpatient/admissions`;if(module==='nursing'){url=`${API}/api/nursing/assessments`;if(body.riskFlags)body.riskFlags=String(body.riskFlags).split(',').map((x:string)=>x.trim()).filter(Boolean);if(body.painScore)body.painScore=Number(body.painScore)}if(module==='surgery'){url=`${API}/api/surgery/cases`;body.consentConfirmed=body.consentConfirmed==='true'}if(module==='maternity'){url=`${API}/api/maternal-care/contacts`;if(body.contactDate)body.contactDate=new Date(body.contactDate).toISOString();for(const k of ['gestationalAgeWeeks','gravida','para','contactNumber','symphysioFundalHeight'])if(body[k]!==undefined&&body[k]!=='')body[k]=Number(body[k])}if(module==='pediatrics'){url=`${API}/api/pediatrics/assessments`;for(const k of ['ageMonths','weightKg','heightCm','muacMm','temperature','respiratoryRate','spo2'])if(body[k]!==undefined&&body[k]!=='')body[k]=Number(body[k])}if(module==='immunization'){url=`${API}/api/immunizations`;if(body.nextDueAt)body.nextDueAt=new Date(body.nextDueAt).toISOString()}if(module==='chronic-care'){url=`${API}/api/chronic-care/records`;if(body.nextReviewAt)body.nextReviewAt=new Date(body.nextReviewAt).toISOString()}if(module==='telemedicine'){url=`${API}/api/telemedicine/sessions`;body.consentConfirmed=body.consentConfirmed==='true'}if(module==='remote-monitoring'){url=`${API}/api/remote-monitoring/readings`;body.valueNumeric=Number(body.valueNumeric);if(body.measuredAt)body.measuredAt=new Date(body.measuredAt).toISOString()}if(module==='patients')body.email=body.email||undefined;
 const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});const out=await r.json();if(!r.ok)throw new Error(out.error||'Request failed');setD({});setMsg('Saved successfully');done()}catch(e:any){if(!navigator.onLine){await enqueueOperation({url,method:'POST',body});setMsg('Saved on this device. It will sync when the connection returns.')}else setMsg(e.message)}finally{setBusy(false)}}
 return <details className="create-record"><summary><span><b>+</b><strong>Create {pretty(module).toLowerCase()}</strong><small>Add a new record here</small></span><em>Open form</em></summary><div className="form-grid">{fs.map(f=>f.options?<label key={f.key}><span>{f.label}</span><select value={d[f.key]??''} onChange={e=>setD({...d,[f.key]:e.target.value})}><option value="">Select {f.label.toLowerCase()}</option>{f.options.map(o=><option key={o}>{o}</option>)}</select></label>:<label key={f.key}><span>{f.label}{f.required?' *':''}</span><input required={f.required} type={f.type||'text'} placeholder={f.placeholder||f.label} value={d[f.key]??''} onChange={e=>setD({...d,[f.key]:e.target.value})}/></label>)}<button className="primary form-submit" disabled={busy||!token} onClick={submit}>{busy?'Saving…':'Create record'}</button>{msg&&<span className="formmsg">{msg}</span>}</div></details>}

function RecordRow({module,row,token,done,openPatient,openEncounter}:{module:string;row:Row;token:string;done:()=>void;openPatient:(id:string)=>void;openEncounter:(row:Row)=>void}){return <article className="record-row"><div className="record-main"><div className="record-avatar">{row.firstName?(row.firstName[0]+(row.lastName?.[0]||'')).toUpperCase():navIcon(module)}</div><div><b>{row.firstName?`${row.firstName} ${row.lastName}`:row.medicationName||row.name||row.title||row.description||row.display||row.reason||row.task||row.code||row.template||row.status||'Record'}</b><span>{row.patientNumber||row.barcode||row.phone||row.priority||row.status||row.createdAt||row.updatedAt||'Record'}</span></div></div><div className="record-meta"><em className={`status-pill ${String(row.status||'active').toLowerCase()}`}>{row.status||'active'}</em><RowActions module={module} row={row} token={token} done={done} openPatient={openPatient} openEncounter={openEncounter}/></div></article>}

function RowActions({module,row,token,done,openPatient,openEncounter}:{module:string;row:Row;token:string;done:()=>void;openPatient:(id:string)=>void;openEncounter:(row:Row)=>void}){const [busy,setBusy]=useState(false);const actions:string[]=[];if(module==='patients')actions.push('360');if(module==='encounters')actions.push('open');if(module==='appointments'&&!['cancelled','completed','no-show','arrived','checked-in'].includes(row.status))actions.push('check-in');if(module==='queue'&&!['completed','cancelled','no-show'].includes(row.status))actions.push(row.status==='waiting'||row.status==='waiting-triage'?'called':row.status==='called'?'in-service':'completed');if(module==='clinical-notes'&&!row.signedAt)actions.push('sign');if(module==='laboratory')actions.push(row.status==='preliminary'?'verify':row.status==='verified'?'release':'');if(module==='pharmacy'&&['active','partially-dispensed'].includes(row.status))actions.push('dispense');if(module==='billing'&&row.status!=='paid')actions.push('pay');if(module==='tasks'&&row.status!=='completed')actions.push('complete');if(module==='referrals'&&row.status==='draft')actions.push('send');if(module==='inpatient')actions.push('discharge');if(module==='emergency'&&row.status!=='disposed')actions.push('disposition');if(module==='telemedicine'&&row.status==='scheduled')actions.push('start');if(module==='telemedicine'&&row.status==='in-progress')actions.push('end');
 const run=async(a:string)=>{if(!a)return;setBusy(true);try{if(a==='360'){openPatient(row.id);return}if(a==='open'){openEncounter(row);return}let url=`${API}/api/actions/${module}/${row.id}/${a}`;let body:any={};if(a==='disposition')url=`${API}/api/emergency/cases/${row.id}/disposition`;if(a==='start')url=`${API}/api/telemedicine/sessions/${row.id}/start`;if(a==='end')url=`${API}/api/telemedicine/sessions/${row.id}/end`;if(a==='pay')body={amount:Number(row.total||0)-Number(row.paidAmount||0),method:'cash'};if(a==='dispense')body={quantity:Number(row.quantity||1)};const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Action failed');done()}catch(e:any){alert(e.message)}finally{setBusy(false)}};
 return <div className="row-actions">{actions.filter(Boolean).map(a=><button key={a} disabled={busy} onClick={()=>run(a)}>{a==='check-in'?'Check in':a==='360'?'Patient 360':a==='open'?'Open':a==='sign'?'Sign':a==='verify'?'Verify':a==='release'?'Release':a==='dispense'?'Dispense':a==='pay'?'Pay':a==='complete'?'Complete':a==='send'?'Send':a==='called'?'Call':a==='in-service'?'Start service':a==='completed'?'Complete':a==='disposition'?'Disposition':a==='start'?'Start visit':a==='end'?'End visit':'Discharge'}</button>)}</div>}

function AIResponse({text}:{text:string}){
 const lines=text.replace(/\r/g,'').replace(/```(?:text|markdown)?/gi,'').split('\n');
 const headingNames=['Answer','Key points','What needs attention','Important','Direct answer','Recorded facts','Reasoning/context','Reasoning and context','Why these items matter','Suggested next review','Suggested review','Uncertainty','Missing or conflicting information','Evidence from record','Sources or records used'];
 const clean=(value:string)=>value.replace(/\*\*/g,'').replace(/^#{1,6}\s*/,'').replace(/^\s*[-•]\s*/,'').replace(/\*+/g,'').trim();
 const isHeading=(value:string)=>{const c=clean(value).replace(/:$/,'').trim();return headingNames.some(h=>c.toLowerCase()===h.toLowerCase())};
 const items:React.ReactNode[]=[]; let bullets:string[]=[];
 const flush=()=>{if(!bullets.length)return;items.push(<ul key={`list-${items.length}`}>{bullets.map((b,i)=><li key={i}>{b}</li>)}</ul>);bullets=[]};
 lines.forEach((raw,i)=>{const trimmed=raw.trim();if(!trimmed)return flush();const bullet=/^(?:[-•*]|\d+[.)])\s+/.test(trimmed);if(bullet){bullets.push(clean(trimmed));return}flush();if(isHeading(trimmed)){items.push(<h3 key={`heading-${i}`}>{clean(trimmed).replace(/:$/,'')}</h3>);return}const value=clean(trimmed);if(value)items.push(<p key={`p-${i}`}>{value}</p>)});flush();
 return <div className="ai-response">{items.length?items:<p>{clean(text)}</p>}</div>;
}

function AIWorkspace({token,patientId}:{token:string;patientId?:string}){
 const [question,setQuestion]=useState(''); const [answer,setAnswer]=useState(''); const [busy,setBusy]=useState(false); const [status,setStatus]=useState<Row>({}); const [role,setRole]=useState('leadership'); const [mode,setMode]=useState('intelligence'); const [run,setRun]=useState<Row>({}); const [brief,setBrief]=useState<Row>({items:[],counts:{}});
 useEffect(()=>{if(!token)return;Promise.all([
   fetch(`${API}/api/ai/status`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()),
   fetch(`${API}/api/ai/brief`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()).catch(()=>({data:{}}))
 ]).then(([a,b])=>{setStatus(a);setBrief(b.data||{})}).catch(()=>{})},[token]);
 async function ask(q=question){if(!q.trim()||busy)return;setBusy(true);setAnswer('');setRun({});const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(`${API}/api/ai/assist`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({patientId:patientId||null,question:q,role,purpose:patientId?'patient-intelligence':'ask-clinai',mode}),signal:controller.signal});const d=await r.json();if(!r.ok)throw new Error(d.error||'ClinAI could not respond');setAnswer(d.data?.answer||'No answer was returned.');setRun(d.data||{});setQuestion('')}catch(e:any){setAnswer(e?.name==='AbortError'?'ClinAI is taking longer than expected. Please try the request again.':(e.message||'ClinAI could not respond.'))}finally{clearTimeout(timeout);setBusy(false)}}
 const prompts=patientId?['What needs my attention about this patient?','Summarize this patient before the visit.','What has changed recently?','What follow-up is outstanding?','Explain the important recent results.']:mode==='analysis'?['Compare this week with the previous week.','What trends are unusual?','Where is the biggest operational pressure?','Calculate the most important service indicators.']:mode==='research'?['Research the latest guidance relevant to today.','Compare approved guidance with our configured pathway.','Find evidence that could improve this workflow.']:['What needs attention across the facility today?','Prepare a leadership briefing for today.','What are the biggest operational pressures?','Summarize clinical attention items.'];
 const roleLabels:Record<string,string>={leadership:'Leadership',doctor:'Doctor',nurse:'Nurse',pharmacist:'Pharmacist',laboratory:'Laboratory',manager:'Manager',district:'District'};
 const modes=[['quick','Quick','Fast lookups and simple questions'],['intelligence','Intelligence','Cross-module reasoning and attention'],['analysis','Analytics','Calculations, trends and complex analysis'],['research','Research','External evidence and approved sources']];
 const counts=brief.counts||{};
 return <section className="ai-workspace"><div className="ai-hero panel"><div className="ai-hero-copy"><span className="section-kicker">CLINAI INTELLIGENCE</span><h2>Understand what matters.</h2><p>ClinAI can retrieve the right records, calculate verified results, connect information across the system and explain what deserves review.</p></div><div className={`ai-status ${status.configured?'ready':'not-ready'}`}><b>{status.configured?'AI ready':'AI not configured'}</b><span>{status.configured?'Intelligence is available':'Connect ClinAI intelligence to continue'}</span></div></div>
 <div className="ai-intelligence-strip"><div><strong>{counts.urgent||0}</strong><span>Urgent review</span></div><div><strong>{counts.attention||0}</strong><span>Needs attention</span></div><div><strong>{(brief.items||[]).length}</strong><span>Signals found</span></div><button className="ghost" onClick={()=>fetch(`${API}/api/ai/brief`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>setBrief(d.data||{}))}>Refresh intelligence</button></div>
 <div className="ai-mode-switch" role="tablist" aria-label="ClinAI intelligence mode">{modes.map(([value,label,desc])=><button key={value} className={mode===value?'active':''} onClick={()=>setMode(value)}><strong>{label}</strong><small>{desc}</small></button>)}</div>
 <div className="ai-grid"><div className="panel ai-chat"><div className="panel-title"><div><span className="section-kicker">CONVERSATION</span><h2>{patientId?'Patient intelligence':'ClinAI intelligence'}</h2></div><label className="ai-role"><span>Role</span><select aria-label="Choose your role" value={role} onChange={e=>setRole(e.target.value)}>{Object.entries(roleLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label></div><div className="ai-prompts">{prompts.map(x=><button key={x} onClick={()=>{setQuestion(x);ask(x)}}>{x}</button>)}</div><textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder={mode==='analysis'?'Ask for a calculation, comparison, trend, forecast, anomaly review, or complex operational analysis…':mode==='research'?'Ask ClinAI to research approved external evidence or compare guidance…':'Ask ClinAI about the patient, today’s work, a result, a care journey, or an operational question…'} aria-label="Ask ClinAI"/><div className="ai-submit-row"><button className="primary" disabled={busy||!question.trim()||!status.configured} onClick={()=>ask()}>{busy?'Working through the request…':'Ask ClinAI'}</button>{busy&&<span className="ai-busy">Reviewing the information you asked about</span>}</div>{answer&&<div className="ai-answer"><div className="ai-answer-head"><strong>ClinAI</strong><span>For professional review</span></div><div className="ai-answer-body"><AIResponse text={answer}/></div></div>}</div>
 <div className="panel ai-attention"><div className="panel-title"><div><span className="section-kicker">INTELLIGENCE</span><h2>What ClinAI can do</h2></div></div><div className="ai-principles"><div><b>1</b><span>SEE THE BIGGER PICTURE</span><small>Bring the information you need about patients, care and facility activity together in one clear view.</small></div><div><b>2</b><span>FIND WHAT NEEDS ATTENTION</span><small>Highlight important results, follow-ups, tasks and other situations that may need your attention.</small></div><div><b>3</b><span>UNDERSTAND YOUR INFORMATION</span><small>Ask questions about patients, results, appointments, care and daily work and get clear answers.</small></div><div><b>4</b><span>MAKE SENSE OF NUMBERS</span><small>Understand trends, changes and important figures without working through the calculations yourself.</small></div><div><b>5</b><span>SUPPORT BETTER DECISIONS</span><small>ClinAI helps you understand the information while healthcare professionals remain responsible for decisions.</small></div></div></div></div></section>
}

function EncounterWorkspace({data,token,close,done}:{data:Row;token:string;close:()=>void;done:()=>void}){const [tab,setTab]=useState('SOAP'),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);const [soap,setSoap]=useState<Row>({noteType:'SOAP'}),[dx,setDx]=useState<Row>({}),[order,setOrder]=useState<Row>({category:'laboratory',priority:'routine'});async function post(url:string,body:Row,success:string){setBusy(true);setMsg('');try{const r=await fetch(`${API}${url}`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');setMsg(success);done();return d}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}return <div className="modalback" onClick={close}><section className="modal encounter-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><span className="section-kicker">PATIENT VISIT</span><h2>Care visit</h2><span>{data.id} · Patient {data.patientId} · {data.status}</span></div><button className="icon-button" onClick={close}>×</button></div><div className="tabs">{['SOAP','DIAGNOSIS','ORDER'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x==='SOAP'?'Visit note':x==='DIAGNOSIS'?'Diagnosis':'Care order'}</button>)}</div>{tab==='SOAP'&&<div className="workspace-form"><textarea placeholder="Subjective" value={soap.subjective||''} onChange={e=>setSoap({...soap,subjective:e.target.value})}/><textarea placeholder="Objective" value={soap.objective||''} onChange={e=>setSoap({...soap,objective:e.target.value})}/><textarea placeholder="Assessment" value={soap.assessment||''} onChange={e=>setSoap({...soap,assessment:e.target.value})}/><textarea placeholder="Plan" value={soap.plan||''} onChange={e=>setSoap({...soap,plan:e.target.value})}/><button className="primary" disabled={busy} onClick={()=>post('/api/clinical-notes',{...soap,encounterId:data.id},'SOAP note saved')}>Save note</button></div>}{tab==='DIAGNOSIS'&&<div className="workspace-form"><input placeholder="ICD-10 code" value={dx.code||''} onChange={e=>setDx({...dx,code:e.target.value})}/><input placeholder="Diagnosis description" value={dx.description||''} onChange={e=>setDx({...dx,description:e.target.value})}/><button className="primary" disabled={busy} onClick={()=>post('/api/diagnoses',{...dx,patientId:data.patientId,encounterId:data.id},'Diagnosis added')}>Add diagnosis</button></div>}{tab==='ORDER'&&<div className="workspace-form"><select value={order.category||'laboratory'} onChange={e=>setOrder({...order,category:e.target.value})}><option value="laboratory">Laboratory</option><option value="imaging">Imaging</option><option value="medication">Medication</option><option value="procedure">Procedure</option></select><input placeholder="Order code" value={order.code||''} onChange={e=>setOrder({...order,code:e.target.value})}/><input placeholder="Description" value={order.description||''} onChange={e=>setOrder({...order,description:e.target.value})}/><select value={order.priority||'routine'} onChange={e=>setOrder({...order,priority:e.target.value})}><option>routine</option><option>urgent</option><option>stat</option></select><button className="primary" disabled={busy} onClick={()=>post('/api/orders',{...order,patientId:data.patientId,encounterId:data.id},'Order placed')}>Place order</button></div>}{msg&&<div className="formmsg workspaceMsg">{msg}</div>}<div className="clinical-note">ClinAI can help organize information and notes. Your care team remains responsible for decisions about each patient.</div></section></div>}

function Patient360({data,token,close,setModule}:{data:Row;token:string;close:()=>void;setModule:(m:string)=>void}){const p=data.patient;const [flow,setFlow]=useState<Row>({});const [timeline,setTimeline]=useState<Row[]>([]);useEffect(()=>{if(!token||!p?.id)return;Promise.all([fetch(`${API}/api/patients/${p.id}/flow`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()),fetch(`${API}/api/patients/${p.id}/timeline`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json())]).then(([a,b])=>{setFlow(a.data||{});setTimeline(b.data||[])})},[token,p?.id]);const counts=[['Visits',data.encounters?.length],['Diagnoses',data.diagnoses?.length],['Orders',data.orders?.length],['Admissions',data.admissions?.length],['Immunizations',data.immunizations?.length],['Long-term care',data.chronicCare?.length],['Remote visits',data.telemedicine?.length],['Monitoring',data.remoteMonitoring?.length]];const stages=[['Registration',true],['Check-in',!!flow.queue?.length],['Triage',!!flow.triage?.length],['Care visit',!!flow.encounters?.length],['Orders',!!flow.orders?.length],['Referral',!!flow.referrals?.length],['Admission',!!flow.admissions?.length],['Follow-up',!!flow.followUp?.length]];return <div className="modalback" onClick={close}><section className="modal patient-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><span className="section-kicker">PATIENT RECORD</span><h2>{p.firstName} {p.middleName||''} {p.lastName}</h2><span>{p.patientNumber} · {p.status} · {p.preferredLanguage||'English'}</span></div><button className="icon-button" onClick={close}>×</button></div><div className="patient-summary"><div><b>Identity</b><p>Date of birth: {p.dateOfBirth||'Not recorded'}</p><p>Sex: {p.sex||'Not recorded'}</p><p>Phone: {p.phone||'Not recorded'}</p><p>Address: {typeof p.address==='string'?p.address:(p.address?.district||p.address?.text||'Not recorded')}</p></div><div><b>Safety</b><p>Allergies: {data.allergies?.length||0}</p>{data.allergies?.slice(0,4).map((x:Row)=><p key={x.id}>{x.substance} · {x.severity||'unspecified'}</p>)}</div><div><b>Clinical activity</b>{counts.map(([n,v])=><p key={String(n)}>{n}: {v??0}</p>)}</div><div><b>Current care</b><p>Active care plans: {data.carePlans?.filter((x:Row)=>x.status==='active').length||0}</p><p>Open referrals: {data.referrals?.filter((x:Row)=>x.status!=='completed').length||0}</p><p>Follow-ups: {data.followUp?.length||0}</p><p>Care alerts: {data.clinicalAlerts?.length||0}</p></div></div><div className="panel journey-card"><div className="panel-title"><div><span className="section-kicker">CARE JOURNEY</span><h2>Where this patient is now</h2></div></div><div className="patient-stage-grid">{stages.map(([name,done])=><button key={String(name)} className={done?'stage-done':''} onClick={()=>setModule(String(name).toLowerCase().replace(' ','-'))}><i>{done?'✓':'•'}</i><span>{name}</span></button>)}</div></div><div className="patienttimeline"><div><h3>Recent care</h3>{timeline.slice(0,12).map((x:Row)=><p key={`${x.kind}-${x.id}`}><b>{x.title||'Care activity'}</b> · {x.status||''}<small>{x.at||''}</small></p>)}</div><div><h3>Recent observations</h3>{data.observations?.slice(0,8).map((x:Row)=><p key={x.id}><b>{x.display||x.code||'Observation'}</b> · {x.valueNumeric??x.valueText??'—'} {x.unit||''}</p>)}</div><div><h3>Medicines</h3>{data.medications?.slice(0,8).map((x:Row)=><p key={x.id}><b>{x.name}</b> {x.strength||''} · {x.dose||''} · {x.frequency||''}</p>)}</div><div><h3>Immunization and monitoring</h3>{data.immunizations?.slice(0,4).map((x:Row)=><p key={x.id}><b>{x.vaccineName}</b> · dose {x.doseNumber||'—'}</p>)}{data.remoteMonitoring?.slice(0,4).map((x:Row)=><p key={x.id}><b>{x.metric}</b> · {x.valueNumeric??'—'} {x.unit||''}</p>)}</div></div><div className="patient-ai-panel"><AIWorkspace token={token} patientId={p.id}/></div><div className="modal-nav">{[['encounters','Care visits'],['orders','Orders'],['laboratory','Laboratory'],['imaging','Imaging'],['pharmacy','Pharmacy'],['referrals','Referrals'],['billing','Billing'],['follow-up','Follow-up']].map(([m,l])=><button key={m} onClick={()=>{setModule(m);close()}}>{l}</button>)}</div></section></div>}
